ient(105deg,#1b2233,#171d2c);border:1px solid var(--line);border-radius:12px 12px 0 0;display:grid;grid-template-columns:1fr 130px 1fr;align-items:center;padding:0 22px}.team-block{display:flex;align-items:center;gap:11px}.team-block.away{justify-content:flex-end;text-align:right}.team-block strong{display:block;font-size:10px;letter-spacing:1.3px}.team-block small{display:block;font-size:8px;color:#7f899d;letter-spacing:1.4px;margin-top:4px;font-weight:700}.team-badge{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;font-size:18px}.blue-badge{background:#5b8cff20;color:#79a1ff;border:1px solid #5b8cff35}.red-badge{background:#ff637420;color:#ff7685;border:1px solid #ff637435}.score-center{display:flex;align-items:center;justify-content:center;gap:10px;position:relative;padding-bottom:12px}.score{font:800 33px/.9 'Barlow Condensed',sans-serif}.score-dash{color:#626d80;font:700 22px 'Barlow Condensed',sans-serif}.match-clock{position:absolute;top:31px;font-size:9px;color:#939caf;letter-spacing:1.5px;font-weight:700}.pitch-frame{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.09);background:#378d55;box-shadow:0 18px 48px #03060d55;line-height:0}canvas{display:block;width:100%;height:auto;aspect-ratio:1000/620;touch-action:none}.pitch-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#07150c08 60%,#06140c32);box-shadow:inset 0 0 60px #06120d33}.center-tip{position:absolute;inset:0;display:grid;place-items:center;background:rgba(8,13,22,.39);backdrop-filter:blur(2px);line-height:normal;transition:opacity .28s,visibility .28s}.center-tip.hidden{opacity:0;visibility:hidden;pointer-events:none}.tip-card{width:min(360px,85%);text-align:center;padding:28px 34px 22px;background:rgba(19,26,40,.93);border:1px solid #ffffff20;border-radius:16px;box-shadow:0 18px 60px #05090b88}.tip-ball{font-size:28px;margin-bottom:10px;filter:drop-shadow(0 4px 8px #0008)}.tip-kicker{font-size:8px;letter-spacing:2.3px;color:var(--lime);font-weight:800}.tip-card h2{font:800 31px/.95 'Barlow Condensed',sans-serif;margin:9px 0;color:#fff}.tip-card p{color:#a7afbd;font-size:11px;margin:8px 0 18px}.play-button{display:flex;align-items:center;justify-content:space-between;width:100%;height:43px;padding:0 16px 0 20px;border:0;border-radius:7px;background:var(--lime);color:#18202a;font:800 10px 'DM Sans',sans-serif;letter-spacing:1.4px;cursor:pointer;transition:transform .15s,filter .15s}.play-button:hover{transform:translateY(-2px);filter:brightness(1.05)}.play-button b{font-size:20px;font-weight:500}.tip-controls{margin-top:16px;color:#d4d8df;font-size:8px;letter-spacing:1px;font-weight:800}.tip-controls span{font-size:7px;color:#8d97a9;margin-left:4px}.tip-controls i{font-style:normal;color:#4e586b;margin:0 8px}.goal-flash{position:absolute;inset:0;display:grid;place-items:center;background:#c8f16922;opacity:0;pointer-events:none;transition:opacity .2s}.goal-flash span{font:900 clamp(48px,10vw,112px)/1 'Barlow Condensed',sans-serif;color:white;text-shadow:0 4px 0 #347340,0 8px 36px #000a;letter-spacing:6px;transform:scale(.75);transition:transform .25s}.goal-flash.show{opacity:1}.goal-flash.show span{transform:scale(1)}.paused-overlay{position:absolute;inset:0;background:#101725ba;backdrop-filter:blur(4px);display:flex;align-items:center;justify-content:center;flex-direction:column;line-height:normal;gap:9px}.paused-overlay.hidden{display:none}.paused-overlay>span{display:grid;place-items:center;width:45px;height:45px;border:1px solid #ffffff28;border-radius:50%;color:var(--lime);font-size:17px}.paused-overlay strong{font:800 27px 'Barlow Condensed',sans-serif;letter-spacing:2px}.paused-overlay small{color:#aab2c1;font-size:10px}.match-footer{height:51px;display:flex;align-items:center;justify-content:space-between;gap:8px}.footer-note{display:flex;align-items:center;gap:8px;font-size:9px;color:#778196}.footer-note b{color:#aeb8c7}.keyboard-icon{font-size:17px;color:#8390a6}.match-controls{display:flex;gap:14px;color:#838da0;font-size:8px;font-weight:700;letter-spacing:.8px}.match-controls span{display:flex;align-items:center;gap:3px}.match-controls kbd{font:700 8px 'DM Sans',sans-serif;color:#c3cad6;padding:3px 4px;border:1px solid #ffffff20;border-radius:3px;background:#1c2332}.side-panel{min-height:100%;display:flex;flex-direction:column;background:linear-gradient(155deg,#1a2131,#151b29);border:1px solid var(--line);border-radius:12px;padding:23px 20px 17px}.panel-heading{display:flex;align-items:center;justify-content:space-between}.panel-heading h2{font:800 24px/.95 'Barlow Condensed',sans-serif;margin:7px 0 0}.trophy{color:var(--lime);font-size:22px}.objective-card{display:flex;align-items:center;gap:12px;margin:24px 0 21px;padding:13px 12px;background:#ffffff06;border:1px solid #ffffff0b;border-radius:8px}.objective-icon{display:grid;place-items:center;width:36px;height:36px;border-radius:9px;background:#c8f16918;color:var(--lime);font-size:22px}.objective-card small,.objective-card strong,.objective-card span{display:block}.objective-card small{font-size:7px;letter-spacing:1.4px;color:#8792a6;font-weight:800}.objective-card strong{font-size:11px;margin-top:4px}.objective-card span{font-size:8px;color:#818b9d;margin-top:3px}.divider{height:1px;background:var(--line);margin-bottom:20px}.section-label{display:flex;justify-content:space-between;font-size:8px;font-weight:800;letter-spacing:1.4px;color:#929db0;margin-bottom:18px}.section-label span{color:#596477}.instruction{display:flex;align-items:flex-start;gap:11px;margin-bottom:19px}.instruction-icon{width:29px;height:29px;flex:none;border-radius:8px;display:grid;place-items:center;font-size:16px}.move-icon{color:#8eaeff;background:#5b8cff18}.shoot-icon{color:#d7f393;background:#c8f16918}.tackle-icon{color:#ff91a0;background:#ff637418}.instruction strong{font-size:10px;display:block;margin:1px 0 4px}.instruction p{font-size:8px;color:#838da0;line-height:1.45;margin:0}.power-meter-wrap{margin-top:auto;padding-top:10px}.power-label{display:flex;justify-content:space-between;color:#8691a5;font-size:8px;font-weight:800;letter-spacing:1.3px;margin-bottom:8px}.power-label span:last-child{color:var(--lime)}.power-track{height:5px;border-radius:4px;background:#ffffff10;overflow:hidden}.power-fill{width:0;height:100%;background:linear-gradient(90deg,#91d552,var(--lime));border-radius:4px;transition:width .08s}.side-bottom{height:42px;border-top:1px solid var(--line);margin-top:17px;padding-top:15px;display:flex;align-items:center;gap:8px;color:#8e98aa;font-size:8px}.pulse-ring{width:6px;height:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 0 4px #c8f16915}.page-footer{height:65px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#586276;font-size:7px;letter-spacing:1.3px;font-weight:800}.page-footer b{color:#ff7180}
